import test from 'node:test';import assert from 'node:assert/strict';import{createHash}from'node:crypto';import{DatabaseSync}from'node:sqlite';import{readFileSync}from'node:fs';
import{prepareSubagentTrackingJson,prepareSqliteSubagentTrackingIdentity}from'./aux-subagent-tracking-identity.mjs';import{PINNED_PROVIDER_STATE_TARGET_DDL}from'./aux-sqlite-provider-identity-schema.mjs';
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const capability={id:'tracking-fixture-scope',disposable:true,exclusive:true,rollbackJournalAbsent:true,assertStopped:async()=>true};
const child={sessionId:'fixture-child',description:'preserve aside prose',model:{provider:'aside',modelId:'same-id',thinkingLevel:'high',fastMode:true},isRunning:false,isBackground:true,unawaited:true};
const state={subagent:{subagents:[child]},todo:{todos:[{provider:'aside',text:'opaque'}]},custom:{provider:'aside'}};
const json=value=>{const bytes=Buffer.from(JSON.stringify(value,null,2));return prepareSubagentTrackingJson({bytes,expectedSha256:sha(bytes)})};
test('exact tracking model token changes; status, model configuration and other state branches remain exact',()=>{
 const bytes=Buffer.from(JSON.stringify(state,null,2)),before=Buffer.from(bytes),result=prepareSubagentTrackingJson({bytes,expectedSha256:sha(bytes)});assert.deepEqual(bytes,before);assert.equal(result.bytes.toString(),bytes.toString().replace('"provider": "aside"','"provider": "aux"  '));assert.equal(result.receipt.changedModels,1);assert.equal(result.bytes.length,bytes.length);assert.deepEqual(JSON.parse(result.bytes),{...state,subagent:{subagents:[{...child,model:{...child.model,provider:'aux'}}]}});assert.equal(json({custom:{provider:'aside'}}).receipt.changedModels,0);
 for(const value of [{subagent:{subagents:[child,child]}},{subagent:{subagents:[{...child,newUnknown:true}]}},{subagent:{subagents:[{...child,model:{provider:'aside',modelId:'x'}}]}},{subagent:{subagents:[],other:1}}])assert.throws(()=>json(value));
 const duplicate=Buffer.from('{"subagent":{"subagents":[],"subagents":[]}}');assert.throws(()=>prepareSubagentTrackingJson({bytes:duplicate,expectedSha256:sha(duplicate)}),/Duplicate/);
});
function fixture(){const db=new DatabaseSync(':memory:');try{db.exec('CREATE TABLE projects(id TEXT PRIMARY KEY NOT NULL);');db.exec(PINNED_PROVIDER_STATE_TARGET_DDL);db.exec('PRAGMA user_version=20; CREATE TABLE opaque(id INTEGER PRIMARY KEY,payload BLOB);');db.prepare('INSERT INTO sessions(id,cwd,tool_state,model) VALUES(?,?,?,?)').run('fixture-parent','/fixture',JSON.stringify(state),' {"provider":"aux","opaque":true} ');db.prepare('INSERT INTO opaque VALUES(?,?)').run(1,Buffer.from([0,255,1]));return Buffer.from(db.serialize())}finally{db.close()}}
test('private SQLite tracking column CAS preserves every other table/column with strict schema and WAL refusal',async()=>{
 const input=fixture(),result=await prepareSqliteSubagentTrackingIdentity({databaseBytes:input,expectedSha256:sha(input),walBytes:null,capability});assert.equal(result.receipt.changedRows,1);assert.equal(result.receipt.changedModels,1);
 const db=new DatabaseSync(':memory:');try{db.deserialize(result.bytes);const row=db.prepare('SELECT * FROM sessions').get();assert.equal(JSON.parse(row.tool_state).subagent.subagents[0].model.provider,'aux');assert.equal(row.model,' {"provider":"aux","opaque":true} ');assert.equal(row.cwd,'/fixture');assert.deepEqual(Buffer.from(db.prepare('SELECT payload FROM opaque').get().payload),Buffer.from([0,255,1]));assert.equal(db.prepare('PRAGMA quick_check').get().quick_check,'ok')}finally{db.close()}
 await assert.rejects(prepareSqliteSubagentTrackingIdentity({databaseBytes:input,expectedSha256:sha(input),walBytes:Buffer.from([1]),capability}),/WAL/);
 await assert.rejects(prepareSqliteSubagentTrackingIdentity({databaseBytes:input,expectedSha256:sha(input),walBytes:null,capability:{...capability,assertStopped:async()=>false}}),/capability/);
});
const pinned=process.env.AUX_PINNED_DAEMON_SOURCE;
test('actual producer, column, update and model-selection source anchors match',{skip:!pinned},()=>{const source=readFileSync(pinned,'utf8'),audit=JSON.parse(readFileSync(new URL('../../docs/integration/proposed/aux-subagent-tracking-identity/source-audit.json',import.meta.url)));assert.equal(sha(Buffer.from(source)),audit.daemonSourceSha256);for(const anchor of audit.anchors)assert.equal(source.split(anchor.find).length-1,anchor.count,anchor.name)});
